package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

type PartRec struct { // 01 PART-REC, 15 bytes
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsLabel string   // PIC X(20) len=20 = SPACES
var WsACount int64   // PIC 99 len=2 = 0
var WsTotalA int64   // PIC 999 len=3 = 0
var WsCount int64    // PIC 999 len=3 = 0

var curRec PartRec
var partLines []string
var partIdx int

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func delimitedBySpace(s string) string {
	if i := strings.IndexByte(s, ' '); i >= 0 {
		return s[:i]
	}
	return s
}

func parseSerial(s string) int64 {
	// s is 4 chars; DISPLAY numeric: digits only
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	var v int64
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c >= '0' && c <= '9' {
			v = v*10 + int64(c-'0')
		}
	}
	return v
}

func MainPara() {
	WsEofFlag = "N"
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	WsTotalA = 0
	WsCount = 0
	// OPEN INPUT PART-FILE
	partLines = nil
	partIdx = 0
	f, err := os.Open("input.dat")
	if err == nil {
		sc := bufio.NewScanner(f)
		// allow long lines
		const maxCap = 1024 * 1024
		buf := make([]byte, 0, 64*1024)
		sc.Buffer(buf, maxCap)
		for sc.Scan() {
			line := sc.Text()
			// strip trailing \r if present (CRLF)
			if len(line) > 0 && line[len(line)-1] == '\r' {
				line = line[:len(line)-1]
			}
			partLines = append(partLines, line)
		}
		f.Close()
	} else {
		if !os.IsNotExist(err) {
			fmt.Fprintln(os.Stderr, err.Error())
			os.Exit(1)
		}
		partLines = nil
	}
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	// CLOSE PART-FILE (nothing to do)
	SummaryPara()
}

func ReadPara() {
	if partIdx >= len(partLines) {
		WsEofFlag = "Y"
		return
	}
	line := partLines[partIdx]
	partIdx++
	// pad with spaces to 15 on right; truncate if longer
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	curRec.LbPart = line[0:8]
	curRec.LbRegion = line[8:11]
	curRec.LbSerial = parseSerial(line[11:15])
}

func ProcessPara() {
	// MOVE SPACES TO WS-LABEL
	WsLabel = strings.Repeat(" ", 20)
	// MOVE 0 TO WS-A-COUNT
	WsACount = 0
	// INSPECT LB-PART TALLYING WS-A-COUNT FOR ALL "A"
	WsACount = int64(strings.Count(curRec.LbPart, "A")) % 100
	// STRING ... INTO WS-LABEL
	p1 := delimitedBySpace(curRec.LbRegion)
	p2 := "-"
	p3 := delimitedBySpace(curRec.LbPart)
	p4 := "-"
	p5 := fmt.Sprintf("%04d", curRec.LbSerial)
	// DELIMITED BY SIZE for p5: exactly 4 chars; handle overflow keep low-order?
	if len(p5) > 4 {
		p5 = p5[len(p5)-4:]
	}
	s := p1 + p2 + p3 + p4 + p5
	if len(s) > 20 {
		s = s[:20]
	}
	WsLabel = padRight(s, 20)
	// INSPECT WS-LABEL REPLACING ALL "0" BY "O"
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")
	// ADD WS-A-COUNT TO WS-TOTAL-A
	WsTotalA = (WsTotalA + WsACount) % 1000
	// ADD 1 TO WS-COUNT
	WsCount = (WsCount + 1) % 1000
	// DISPLAY WS-LABEL " A=" WS-A-COUNT
	fmt.Printf("%s A=%02d\n", WsLabel, WsACount)
	ReadPara()
}

func SummaryPara() {
	fmt.Printf("LABELS: %03d A-TOTAL: %03d\n", WsCount, WsTotalA)
}

func main() {
	MainPara()
}
